/** Consents still to take or to scan — GET /api/v1/consent-worklist (who may call: holders of consent.view). */
export function worklistConsent(query?: { days?: number; mine?: boolean }): Promise<ConsentWorklistItemOut[]> {
  return api<ConsentWorklistItemOut[]>("GET", withQuery(`/consent-worklist`, query), undefined);
}

/** The consent register — GET /api/v1/consents (who may call: holders of consent.view). */
export function listConsents(query?: { patient_id?: number | null; admission_id?: number | null; booking_id?: number | null; status?: "Draft" | "Given" | "Refused" | "Withdrawn" | "Cancelled" | null; category?: "General" | "Procedure" | "Anaesthesia" | "Transfusion" | "HighRiskTreatment" | "AgainstMedicalAdvice" | "Other" | null; date_from?: string | null; date_to?: string | null; unscanned?: boolean; limit?: number }): Promise<ConsentBriefOut[]> {
  return api<ConsentBriefOut[]>("GET", withQuery(`/consents`, query), undefined);
}

/** The situations that need a consent, with their forms — GET /api/v1/consent-forms (who may call: holders of consent.view or consent.configure). */
export function listForms(query?: { include_inactive?: boolean }): Promise<ConsentFormOut[]> {
  return api<ConsentFormOut[]>("GET", withQuery(`/consent-forms`, query), undefined);
}

/** Who decides for a patient who cannot — GET /api/v1/consent-decision-makers (who may call: holders of consent.view or consent.configure). */
export function listDecisionMakers(): Promise<DecisionMakerOut[]> {
  return api<DecisionMakerOut[]>("GET", `/consent-decision-makers`, undefined);
}

/** Prepare a consent form — POST /api/v1/consents (who may call: holders of consent.record). */
export function createConsents(body: ConsentIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents`, body, { idempotent: true });
}

/** A consent — GET /api/v1/consents/{consent_id} (who may call: holders of consent.view). */
export function getConsent(consent_id: number): Promise<ConsentOut> {
  return api<ConsentOut>("GET", `/consents/${consent_id}`, undefined);
}

/** Edit a prepared consent — PATCH /api/v1/consents/{consent_id} (who may call: holders of consent.record). */
export function update(consent_id: number, body: ConsentUpdateIn): Promise<ConsentOut> {
  return api<ConsentOut>("PATCH", `/consents/${consent_id}`, body);
}

/** The consent form (A4) — GET /api/v1/consents/{consent_id}/print-payload (who may call: holders of consent.view). */
export function printConsent(consent_id: number): Promise<PrintOut_ConsentPrintFieldsOut_> {
  return api<PrintOut_ConsentPrintFieldsOut_>("GET", `/consents/${consent_id}/print-payload`, undefined);
}

/** The consent form as a PDF — GET /api/v1/consents/{consent_id}/pdf (who may call: holders of consent.view). */
export function consentPdf(consent_id: number): Promise<unknown> {
  return api<unknown>("GET", `/consents/${consent_id}/pdf`, undefined);
}

/** Record a consent as given — POST /api/v1/consents/{consent_id}/sign (who may call: holders of consent.record). */
export function sign(consent_id: number, body: ConsentSignIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents/${consent_id}/sign`, body);
}

/** Record an informed refusal — POST /api/v1/consents/{consent_id}/refuse (who may call: holders of consent.record). */
export function refuse(consent_id: number, body: ConsentRefuseIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents/${consent_id}/refuse`, body);
}

/** Withdraw a given consent — POST /api/v1/consents/{consent_id}/withdraw (who may call: holders of consent.record). */
export function withdrawConsents(consent_id: number, body: ConsentReasonIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents/${consent_id}/withdraw`, body, { idempotent: true });
}

/** Cancel a prepared consent — POST /api/v1/consents/{consent_id}/cancel (who may call: holders of consent.record). */
export function cancelConsents(consent_id: number, body: ConsentReasonIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents/${consent_id}/cancel`, body, { idempotent: true });
}

/** Attach the scan of the signed form — POST /api/v1/consents/{consent_id}/scan (who may call: holders of consent.record). */
export function scanConsents(consent_id: number, body: ConsentScanIn): Promise<ConsentOut> {
  return api<ConsentOut>("POST", `/consents/${consent_id}/scan`, body);
}

/** Upload a patient document (PDF/JPEG/PNG) — POST /api/v1/patients/{patient_id}/documents (who may call: holders of patient.document.upload). */
export function uploadDocumentPatientsDocuments(patient_id: number, body: FormData): Promise<PatientDocumentUploadOut> {
  return api<PatientDocumentUploadOut>("POST", `/patients/${patient_id}/documents`, body, { idempotent: true });
}
